<template>
  <LargeAlert
    :description="processedTitle"
    :icon="Spinner"
    :icon-class="spinnerClass"
    :card="variants[variant].card"
    :class="cn('w-full mx-auto p-0 px-0 sm:px-8 flex items-center justify-center', variants[variant].class)"
  >
    <slot />
  </LargeAlert>
</template>

<script lang="ts" setup>
import { cn } from '@/lib/utils';
import { Spinner } from '~/assets/icons';

const props = defineProps({
  subject: { type: String, default: '' },
  title: { type: String, default: 'Loading' },
  variant: {
    type: String as PropType<'fullscreen' | 'inline' | 'table'>,
    default: 'fullscreen',
  },
  spinnerClass: { type: String, default: 'fill-foreground w-8 h-8' },
});

const variants = {
  inline: {
    card: false,
    class: 'min-h-48 py-4',
  },
  fullscreen: {
    card: true,
    class: 'min-h-80',
  },
  table: {
    card: false,
    class: 'min-h-48 pb-6 pt-0',
  },
};

const processedTitle = computed(() => {
  if (!props.title && !props.subject) return '';
  return `${props.title}${props.subject ? ` ${props.subject}` : ''}...`;
});
</script>

<style lang="scss" scoped></style>
